// ❌ OLD: Writing custom JavaScript regex validators, error display managers,
// and manual submit blocking logic for basic form inputs.
function validateForm(e) {
  e.preventDefault();
  const email = document.getElementById('email').value;
  if (!email.includes('@') || email.length < 5) {
    document.getElementById('err').textContent = 'Invalid email';
    return false;
  }
  submitViaAjax();
}
